/// <summary>
/// HSMobileOpsCountRequestSvc's answer. Status: Open, Counting, CreatingJournal, JournalCreated, Posted or
/// Cancelled. PayloadJson: the counts (listCounts), the requested items (getCountItems) or the results
/// [{ItemId, ItemName, ConfigId, SizeId, ColorId, StyleId, BatchId, SerialId, LocationId, Counted, OnHand, Variance}].
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountReqResponse
{
    boolean success;
    str errorCode;
    str message;
    str masterId;
    str reference;
    str status;
    str journalId;
    boolean posted;
    boolean existing;
    str payloadJson;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

