public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('MasterId')]
public str parmMasterId(str _value = masterId)
{
    masterId = _value;
    return masterId;
}

[DataMemberAttribute('Reference')]
public str parmReference(str _value = reference)
{
    reference = _value;
    return reference;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('JournalId')]
public str parmJournalId(str _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('Posted')]
public boolean parmPosted(boolean _value = posted)
{
    posted = _value;
    return posted;
}

[DataMemberAttribute('Existing')]
public boolean parmExisting(boolean _value = existing)
{
    existing = _value;
    return existing;
}

[DataMemberAttribute('PayloadJson')]
public str parmPayloadJson(str _value = payloadJson)
{
    payloadJson = _value;
    return payloadJson;
}
